// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 1 ether);
        uint256 lockBlock = block.number;

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Target block is lockBlock + 1; settling IN that block must revert
        // because settle requires block.number strictly greater than target.
        vm.roll(lockBlock + 1);

        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
